338	int do_kill(pid_t pid)
339	{
340	    disable_preempt();
341	
342	    pcb_t *victim = NULL;
343	    for (int i = 0; i < NUM_MAX_TASK; i++) {
344	        if (pcb[i].pid == pid) {
345	            victim = &pcb[i];
346	            break;
347	        }
348	    }
349	    if (victim == NULL || victim->status == TASK_EXITED ||
350	        victim->status == TASK_ZOMBIE || victim->status == TASK_KILLED) {
351	        enable_preempt();
352	        return 0;
353	    }
354	
355	    if (victim == current_running[cpu_id]) {
356	        /* killing ourselves is just an exit */
357	        enable_preempt();
358	        do_exit();
359	        return 1;
360	    }
361	
362	    release_resources(victim);
363	
364	    if (victim->status == TASK_RUNNING) {
365	        /* it is running on the other hart, and its page table is live there:
366	         * flag it and let that hart finish the teardown when it reschedules */
367	        victim->status = TASK_KILLED;
368	    } else {
369	        free_process_user_page(victim->pgdir);
370	        victim->pgdir = (PTE*)PGDIR_PA;
371	        reclaim_pcb(victim);
372	    }
373	
374	    enable_preempt();
375	    return 1;
376	}
